import {GAME_NIGHT_STORE,staffButton} from './shop-staff.js?v=72.0.0';
export function shopRows(s,{E,esc},query='',floor='all',availability='ready'){
 const normalize=v=>String(v).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const all=[...new Set(E.mallOf(s).sections.flatMap(d=>d.stores))].map(E.storeById).filter(Boolean);
 const rows=all.filter(st=>(floor==='all'||E.storeFloor(E.mallOf(s),st.id)===Number(floor))&&(availability==='saved'?(s.savedShops||[]).includes(st.id):availability==='studios'?E.isPlanningStore(st):availability==='all'||st.count||E.isServiceStore(st)||st.businessKind==='food'||st.id===GAME_NIGHT_STORE)&&normalize(st.name+' '+st.range).includes(normalize(query))).sort((a,b)=>(E.storeFloor(E.mallOf(s),a.id)!==(s.floor||0))-(E.storeFloor(E.mallOf(s),b.id)!==(s.floor||0))||a.name.localeCompare(b.name));
 return `<p class="shop-results-count" role="status">${rows.length} matching shops · ${availability==='saved'?'Your saved shops':availability==='ready'?'Collections, services & activities':availability==='studios'?'Original material studios · catalogs in research':'All locations'}</p>${rows.map(st=>`<button class="shop-destination" data-action="visit" data-id="${st.id}"><span class="shop-monogram" style="--shop:${st.color}">${esc(st.name.slice(0,2))}</span><span><strong>${esc(st.name)}</strong><small>${esc(E.planFor(s).levels[E.storeFloor(E.mallOf(s),st.id)])} · ${st.count?st.count+' real products':E.isServiceStore(st)?'Bookable services':st.businessKind==='food'?'Game dining · original menu':st.id===GAME_NIGHT_STORE?'Free tabletop demos':'Material studio · collection in research'}</small><b>Walk here & enter →</b></span></button>`).join('')||(availability==='saved'&&!query?'<p>No saved shops in this center yet. Open a shop’s guide and choose Save this shop.</p>':'<p>No shops match. Try another name or floor.</p>')}`;
}
export function shoppingGuide(s,id,{E,esc},count=0){
 const st=id&&E.storeById(id);
 if(!st)return `<div class="eyebrow">YOUR SHOPPING DAY</div><h2>Make a little discovery.</h2><p>Browse a shop, meet a friend or take a break. Your map connects every floor.</p><button class="button orange wide" data-action="map-panel" data-id="shops">Find a shop</button><button class="button secondary wide" data-action="center-map">Map & things to do</button><details class="guide-more"><summary>Plans, stories & more</summary><div class="play-detours"><button data-action="map-panel" data-id="services">Rest, food & friends</button><button data-action="plan-notebook">My shopping shortlists</button><button data-action="commons-notebook">My discoveries · ${E.commonsStatus(s).count}/3</button><button data-action="view" data-id="journal">Stories & shared afternoons</button><button data-action="view" data-id="wardrobe">My purchases & outfits</button><button data-action="end-day">Go home & sleep</button></div></details>`;
 if(st.businessKind==='food'&&!st.count)return `<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>Take a break with an original Mallside game meal. Review the price, then walk to a seat to dine.</p><button class="button orange wide" data-action="dining-open">Dining menu</button><button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`;
 if(st.id===GAME_NIGHT_STORE)return `<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>Walk to Taylor’s table for solo matches, guided turns, and tabletop challenges. The merchandise collection is still being researched.</p><button class="button orange wide" data-action="staff-open" data-id="${esc(st.id)}">Plan a game night</button><details class="guide-more"><summary>More shop activities</summary><div class="play-detours"><button data-action="studio-open">Explore the material study</button><button data-action="shop-plan-open">Open the shopping desk</button><button data-action="interior-browse">Browse the shop guide</button></div></details><button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`;
 const storage=st.products.some(p=>p.storageProfile),planter=st.products.some(p=>p.ceramicProfile?.planter),notebook=st.products.some(p=>p.stationeryProfile),frames=st.products.some(p=>p.frameProfile),service=E.isServiceStore(st),pending=!service&&!st.count,steps=service?[['Choose a service','Read the time, price and recovery.'],['Reserve in game','Bookings appear below the menu.'],['Enjoy or refund','Use it here, or refund an unused booking.']]:pending?[['Explore a material study','Try original palettes and finishes.'],['Build a shortlist','Compare verified finds and set a game budget.'],['Walk to a find','Visit the named shop to inspect and check out.']]:[['Browse & inspect','Read a label or choose a product.'],[frames?'Choose a frame width':st.products.some(E.canTry)?'Choose your size':storage?'Inspect a storage box':planter?'Inspect a planter':notebook?'Browse a notebook':st.businessKind==='books'?'Browse an edition':'Explore a demo',frames?'Compare width labels and preview the frame.':st.products.some(E.canTry)?'Try eligible clothes before buying.':storage?'Check single-box dimensions and contents before choosing.':planter?'Check dimensions, drainage and selected color before choosing.':notebook?'Check the B6 format, paper and binding before choosing.':st.businessKind==='books'?'Check the format and ISBN before choosing.':'Read the label and try a product demo.'],['Review & pay','Only checkout spends game money.']];
 return `<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>${service?'Choose a booking, enjoy a session or manage unused reservations.':pending?'This collection is still being researched. Explore the original studio or plan a visit to a stocked shop.':'Inspect a real product, then review your bag before paying.'}</p><details class="guide-steps"><summary>How this shop works</summary><ol class="shopping-steps">${steps.map(([title,detail],i)=>`<li><b>${i+1}</b><span>${title}<small>${detail}</small></span></li>`).join('')}</ol></details><button class="button orange wide" data-action="${pending?'studio-open':'interior-browse'}">${service?'Services & my bookings':pending?'Explore the material study':'Browse this shop'}</button>${staffButton(st,esc)}${!service?`<button class="button secondary wide" data-action="${pending?'shop-plan-open':'play-bag'}">${pending?'Open the shopping desk':'Review bag'+(count?' · '+count+(count===1?' item':' items'):'')}</button>`:''}${!pending&&!service&&st.products.some(E.canTry)?`<button class="button secondary wide" data-action="fitting-open" data-id="${esc(st.id)}">Fitting room</button>`:''}<button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`;
}
export {campusMapSVG} from './center-map-view.js?v=56.0.0';

export function shopFinderShortcuts(s,availability,{E}){const ids=new Set(E.mallOf(s).sections.flatMap(d=>d.stores)),count=(s.savedShops||[]).filter(id=>ids.has(id)).length;return `<div class="shop-finder-quick" role="group" aria-label="Shop list shortcuts"><button class="button secondary" data-action="shop-finder-mode" data-id="ready" aria-pressed="${availability==='ready'}">Collections & activities</button><button class="button secondary" data-action="shop-finder-mode" data-id="studios" aria-pressed="${availability==='studios'}">Material studios</button><button class="button secondary" data-action="shop-finder-mode" data-id="saved" aria-pressed="${availability==='saved'}">Saved shops · ${count}</button><button class="button secondary" data-action="plan-notebook">My shortlists · ${s.shoppingPlans.length}</button></div>`;}

export function playNeeds(s){return [['Stamina',s.energy],['Fullness',s.hunger]].map(([name,value])=>`<span class="play-need ${value<25?'low':''}" aria-label="${name} ${Math.ceil(value)} out of 100"><span>${name}<strong>${Math.ceil(value)}</strong></span><i aria-hidden="true" style="--need:${Math.max(0,Math.min(100,value))}%"></i></span>`).join('');}
